questionvariables.text:
cosd(x) := cos(x*%pi/180);
sind(x) := sin(x*%pi/180);
atand(x) := 180*atan(x)/%pi;
asind(x) := 180*asin(x)/%pi;
two(v) := if v < 10 then sconcat("0", string(v)) else string(v);
hm(m) := block([q], q: mod(m, 1440), sconcat(two(floor(q/60)), ":", two(mod(q, 60))));
dmx(m) := sconcat(string(floor(m/60)), "^\\circ", two(mod(m, 60)), "'");
/* Design: great-circle distance along a meridian, in km. [latP deg, min, N/S, latQ deg, min, N/S, longitude E]. Angles in minutes. Source: adapted from SMP Book 5 (Metric), chapter 3, Exercise D question 8. */
L: [[3,15,"N",11,40,"N",38],[2,50,"S",9,25,"N",41],[6,20,"S",14,5,"S",42],[1,35,"N",4,50,"S",36],[12,10,"N",25,45,"N",55],[7,55,"S",3,20,"N",40],[18,30,"S",4,45,"S",57],[0,40,"N",13,25,"S",44],[5,5,"N",21,50,"N",48],[9,45,"S",2,10,"N",39]];
ix: 1+rand(10);
E: L[ix];
lon: E[7];
a: 60*E[1]+E[2]; b: 60*E[4]+E[5];
same: is(E[3]=E[6]);
nm: if same then abs(a-b) else a+b;
wr: if same then a+b else abs(a-b);
D: floor(nm/60); M: mod(nm,60);
kmv: nm/60/360*40040;
kmtol: max(1,kmv/1000);
/* diagnostics */
dec: (D+M/100)*60; deg: nm/60; half: kmv/2; divnm: nm/1.853;
deckm: (D+M/100)/360*40040; rulekm: wr/60/360*40040;
hi: max(a,b); lo: min(a,b);

feedbackvariables.text:
ft: is(abs(ans1-nm)>0.001 and abs(ans2-ans1*1.853)<=kmtol);
yr: if ans1>0 then float(ans2/ans1) else 0;
yshow: is(ans1>0 and abs(yr-1.853)>0.002);
